`timescale 1ns/1ps

module safety_riscv_soc_stage1_tb;

  logic clk;
  logic rst_ni;

  initial begin
    clk = 1'b0;
    forever #5 clk = ~clk;
  end

  initial begin
    rst_ni = 1'b0;
    repeat (10) @(posedge clk);
    rst_ni = 1'b1;
    $display("[%0t] Reset released", $time);
  end

  safety_riscv_soc_stage1 dut (
    .clk_i  (clk),
    .rst_ni (rst_ni)
  );

  /*
   * Diagnostic monitor:
   * Print every data-memory write generated by Ibex.
   */
  always @(posedge clk) begin
    if (rst_ni &&
        dut.u_ram.a_req_i &&
        dut.u_ram.a_we_i) begin

      $display("[%0t] RAM WRITE: addr = 0x%08h, data = 0x%08h (%0d), be = 0x%01h",
               $time,
               dut.u_ram.a_addr_i,
               dut.u_ram.a_wdata_i,
               dut.u_ram.a_wdata_i,
               dut.u_ram.a_be_i);

      if (dut.u_ram.a_wdata_i == 32'd42) begin
        $display("[%0t] STAGE1 PASS: expected data value 42 observed",
                 $time);
        $finish;
      end
    end
  end

  initial begin
    #200000;
    $display("[%0t] STAGE1 FAIL: No expected RAM write observed",
             $time);
    $finish;
  end

endmodule
